def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

P = lambda n: n**3 + 4*n**2 + 6*n + 4

test_n = [6, 7, 8, 9, 10]
results = {}

for n in test_n:
    Pn = P(n)
    factors = prime_factorization(Pn)
    results[n] = {
        "Pn": Pn,
        "Factors": factors,
        "Only2_5": all(p in [2, 5] for p in factors.keys())
    }

print("Results:")
for n, data in results.items():
    print(f"n={n}: P(n) = {data['Pn']}")
    print(f"  Prime Factors: {data['Factors']}")
    print(f"  Only 2 and 5 factors: {data['Only2_5']}")

